/**
 * Transparent, rule-based insights.
 *
 * Every insight is derived from computed simulation numbers by an explicit
 * rule; the `rule` field documents the rule so users can audit it. No text is
 * generated by a language model.
 */
import type { MetricKey, Scenario, SimulationResult } from "@/domain/types";
import { getObjective, type KpiDefinition } from "@/domain/objectives";
import { SEGMENTS } from "@/domain/labels";
import { formatCurrency, formatMetric, formatNumber, formatPercent, formatSignedPercent } from "@/lib/format";
import { describeReward, thresholdOf } from "./conditions";
import { safeDiv } from "./math";

export type InsightTone = "positive" | "warning" | "neutral" | "info";

export interface Insight {
  id: string;
  tone: InsightTone;
  title: string;
  detail: string;
  rule: string;
}

export function metricValue(r: SimulationResult, key: MetricKey): number {
  return r[key] as number;
}

/** Insights for a single simulation result. */
export function resultInsights(r: SimulationResult): Insight[] {
  const out: Insight[] = [];
  const naturalShare = safeDiv(r.naturalQualifiers, r.qualifiedCustomers);

  if (r.eligibleCustomers === 0) {
    out.push({
      id: "no-eligible",
      tone: "warning",
      title: "Uygun müşteri bulunamadı",
      detail: "Seçilen kitle bu kampanya hedefinin uygunluk kurallarını karşılamıyor. Farklı bir kitle veya hedef seçin.",
      rule: "uygun müşteri = 0",
    });
    return out;
  }

  if (naturalShare >= 0.5) {
    out.push({
      id: "natural-share",
      tone: "warning",
      title: "Ödüllerin önemli kısmı davranış değişikliği yaratmayabilir",
      detail: `Hak kazananların yaklaşık ${formatPercent(naturalShare)}'inin kampanya olmadan da koşulu sağlaması bekleniyor. Koşulu zorlaştırmak veya kitleyi daraltmak maliyet verimliliğini artırabilir.`,
      rule: "kampanyasız hak kazanan / toplam hak kazanan ≥ %50 (karşı-olgusal varsayım)",
    });
  } else if (naturalShare <= 0.25 && r.qualifiedCustomers > 0) {
    out.push({
      id: "natural-share-low",
      tone: "positive",
      title: "Hak kazananların çoğu kampanyayla harekete geçiyor",
      detail: `Hak kazananların yalnızca ${formatPercent(naturalShare)}'inin kampanyasız da koşulu sağlaması bekleniyor.`,
      rule: "kampanyasız hak kazanan / toplam hak kazanan ≤ %25",
    });
  }

  if (r.budgetCapped) {
    const unserved = r.unconstrainedQualified - r.qualifiedCustomers;
    out.push({
      id: "budget-capped",
      tone: "warning",
      title: "Bütçe beklenen talebi karşılamıyor",
      detail: `Bütçe sınırsız olsaydı ${formatNumber(r.unconstrainedQualified)} müşterinin hak kazanması beklenirdi. Bütçe dolduğunda kampanya kapanacağı için yaklaşık ${formatNumber(unserved)} müşteri kampanyadan yararlanamayabilir.`,
      rule: "beklenen ödül maliyeti > bütçe → sonuçlar bütçe / maliyet oranında ölçeklenir",
    });
  } else if (r.budgetUtilization < 0.5) {
    out.push({
      id: "budget-low",
      tone: "info",
      title: "Bütçenin yarısından azı kullanılıyor",
      detail: `Beklenen maliyet bütçenin ${formatPercent(r.budgetUtilization)}'i. Bütçenin bir kısmı başka senaryolara ayrılabilir.`,
      rule: "bütçe kullanımı < %50",
    });
  }

  if (r.incrementalSpending > 0 && r.costToIncrementalRatio > 0.5 && ["spending_growth", "category_growth"].includes(r.objective)) {
    out.push({
      id: "cost-ratio",
      tone: "warning",
      title: "Ek ciroya göre maliyet yüksek",
      detail: `Her 1 TL tahmini ek ciro için ${formatMetric(r.costToIncrementalRatio, "ratio")} TL ödül maliyeti bekleniyor.`,
      rule: "maliyet / ek ciro > 0,50",
    });
  }

  const segs = r.segments.filter((s) => s.eligibleCustomers >= 1000);
  if (segs.length >= 2) {
    const best = segs.reduce((a, b) => (b.qualificationRate > a.qualificationRate ? b : a));
    const worst = segs.reduce((a, b) => (b.qualificationRate < a.qualificationRate ? b : a));
    if (best.qualificationRate > worst.qualificationRate * 1.5) {
      out.push({
        id: "segment-spread",
        tone: "neutral",
        title: "Segmentler arasında belirgin fark var",
        detail: `${SEGMENTS[best.segmentId].name} segmentinde beklenen oran ${formatPercent(best.qualificationRate, 1)}, ${SEGMENTS[worst.segmentId].name} segmentinde ${formatPercent(worst.qualificationRate, 1)}. Segment bazlı farklı koşullar değerlendirilebilir.`,
        rule: "en yüksek segment oranı > en düşük segment oranı × 1,5",
      });
    }
  }

  if (r.reliability.level === "dusuk") {
    out.push({
      id: "reliability",
      tone: "warning",
      title: "Senaryo güvenilirliği düşük",
      detail: r.reliability.notes[0] ?? "Veri kapsamı veya geçmiş kampanya sayısı yetersiz.",
      rule: "veri kapsamı, desteklenen aralık ve benzer kampanya sayısı kurallarından en az ikisi sağlanmıyor",
    });
  }
  return out;
}

// ---------------------------------------------------------------------------
// Scenario comparison
// ---------------------------------------------------------------------------

export type OptimizationGoal = "none" | "max_incremental" | "max_conversions" | "min_cost" | "max_efficiency";

export const OPTIMIZATION_LABELS: Record<OptimizationGoal, string> = {
  none: "Optimizasyon hedefi seçilmedi",
  max_incremental: "Beklenen ek ciroyu en üst düzeye çıkar",
  max_conversions: "Beklenen dönüşümü (hak kazanan) en üst düzeye çıkar",
  min_cost: "Beklenen maliyeti en aza indir",
  max_efficiency: "Bütçe kısıtı altında verimliliği en üst düzeye çıkar",
};

export interface OptimizationConstraints {
  maxBudget?: number;
  minQualified?: number;
}

export interface RankedScenario {
  id: string;
  feasible: boolean;
  reasons: string[];
  score: number;
  rank: number | null;
}

/** Ranks scenarios ONLY for an explicit optimisation goal + constraints. */
export function rankScenarios(
  scenarios: Scenario[],
  goal: OptimizationGoal,
  c: OptimizationConstraints,
): RankedScenario[] {
  if (goal === "none") return scenarios.map((s) => ({ id: s.id, feasible: true, reasons: [], score: 0, rank: null }));
  const rows = scenarios.map((s) => {
    const r = s.result;
    const reasons: string[] = [];
    if (c.maxBudget && r.totalCost > c.maxBudget) reasons.push(`Maliyet ${formatCurrency(r.totalCost)} > limit ${formatCurrency(c.maxBudget)}`);
    if (c.minQualified && r.qualifiedCustomers < c.minQualified)
      reasons.push(`Hak kazanan ${formatNumber(r.qualifiedCustomers)} < asgari ${formatNumber(c.minQualified)}`);
    if (goal === "max_incremental" && !r.incrementalValidated) reasons.push("Ek ciro tahmini doğrulanmadı");
    const score =
      goal === "max_incremental"
        ? r.incrementalSpending
        : goal === "max_conversions"
          ? r.qualifiedCustomers
          : goal === "min_cost"
            ? -r.totalCost
            : // efficiency: incremental outcome per TL of cost
              safeDiv(r.objective === "spending_growth" || r.objective === "category_growth" ? r.incrementalSpending : r.qualifiedCustomers, r.totalCost);
    const blocking = reasons.filter((x) => x !== "Ek ciro tahmini doğrulanmadı");
    return { id: s.id, feasible: blocking.length === 0, reasons, score, rank: null as number | null };
  });
  const sorted = rows.filter((r) => r.feasible).sort((a, b) => b.score - a.score);
  sorted.forEach((r, i) => (r.rank = i + 1));
  return rows;
}

function pctDiff(a: number, b: number): number {
  return safeDiv(b - a, Math.abs(a));
}

/** Pairwise trade-off insights relative to the first (reference) scenario. */
export function comparisonInsights(scenarios: Scenario[]): Insight[] {
  if (scenarios.length < 2) return [];
  const out: Insight[] = [];
  const objectives = new Set(scenarios.map((s) => s.objective));
  if (objectives.size > 1) {
    out.push({
      id: "mixed-objectives",
      tone: "warning",
      title: "Farklı kampanya hedefleri karşılaştırılıyor",
      detail: "Seçilen senaryoların hedefleri farklı olduğu için hak kazanma ve dönüşüm metrikleri doğrudan karşılaştırılabilir değildir. Maliyet ve bütçe metriklerine odaklanın.",
      rule: "senaryo hedefleri aynı değil",
    });
  }

  const [ref, ...others] = scenarios;
  for (const s of others) {
    const a = ref.result;
    const b = s.result;
    const dInc = pctDiff(a.incrementalSpending, b.incrementalSpending);
    const dCost = pctDiff(a.totalCost, b.totalCost);
    const dQ = pctDiff(a.qualifiedCustomers, b.qualifiedCustomers);

    const changes = parameterChanges(ref, s);
    const prefix = changes.length ? `${changes.join("; ")}. ` : "";

    if (dInc > 0.05 && dCost > 0.05) {
      out.push({
        id: `tradeoff-${s.id}`,
        tone: "neutral",
        title: `${s.name}: daha fazla ek ciro, daha yüksek maliyet`,
        detail: `${prefix}Referans senaryoya (${ref.name}) göre ${formatPercent(dInc)} daha fazla tahmini ek ciro, ancak ${formatPercent(dCost)} daha yüksek maliyet bekleniyor.`,
        rule: "Δ ek ciro > +%5 ve Δ maliyet > +%5",
      });
    } else if (dInc >= -0.02 && dCost < -0.05) {
      out.push({
        id: `dominant-cost-${s.id}`,
        tone: "positive",
        title: `${s.name}: benzer ek ciro, daha düşük maliyet`,
        detail: `${prefix}Referans senaryoya göre maliyet ${formatPercent(-dCost)} düşerken tahmini ek ciro korunuyor (Δ ${formatSignedPercent(dInc)}).`,
        rule: "Δ ek ciro ≥ −%2 ve Δ maliyet < −%5",
      });
    } else if (dInc < -0.05 && dCost < -0.05) {
      out.push({
        id: `cheaper-${s.id}`,
        tone: "neutral",
        title: `${s.name}: daha düşük maliyet, daha az ek ciro`,
        detail: `${prefix}Maliyet ${formatPercent(-dCost)} azalıyor, tahmini ek ciro ise ${formatPercent(-dInc)} düşüyor.`,
        rule: "Δ ek ciro < −%5 ve Δ maliyet < −%5",
      });
    } else if (dInc < -0.05 && dCost > 0.05) {
      out.push({
        id: `dominated-${s.id}`,
        tone: "warning",
        title: `${s.name}: daha yüksek maliyet, daha az ek ciro`,
        detail: `${prefix}Referans senaryoya göre maliyet ${formatPercent(dCost)} daha yüksek, tahmini ek ciro ise ${formatPercent(-dInc)} daha düşük.`,
        rule: "Δ ek ciro < −%5 ve Δ maliyet > +%5",
      });
    }

    if (Math.abs(dQ) > 0.1) {
      out.push({
        id: `conv-${s.id}`,
        tone: dQ > 0 ? "positive" : "info",
        title: `${s.name}: hak kazanan sayısında ${dQ > 0 ? "artış" : "azalış"}`,
        detail: `Beklenen hak kazanan müşteri ${formatNumber(a.qualifiedCustomers)} → ${formatNumber(b.qualifiedCustomers)} (${dQ > 0 ? "+" : "−"}${formatPercent(Math.abs(dQ))}).`,
        rule: "|Δ hak kazanan| > %10",
      });
    }
  }

  for (const s of scenarios) {
    if (s.result.budgetCapped) {
      out.push({
        id: `capped-${s.id}`,
        tone: "warning",
        title: `${s.name}: bütçe sınırına takılıyor`,
        detail: `Beklenen talep bütçeyi aşıyor; sonuçlar bütçe oranında ölçeklendi. Bütçe kullanımı ${formatPercent(s.result.budgetUtilization)}.`,
        rule: "beklenen ödül maliyeti > bütçe",
      });
    }
  }
  if (scenarios.some((s) => s.result.reliability.level === "dusuk")) {
    out.push({
      id: "reliability",
      tone: "info",
      title: "Karşılaştırmanın güvenilirliği sınırlı",
      detail:
        "Bazı senaryolar geçmiş veriyle desteklenen parametre aralıklarının dışında veya veri kapsamı düşük. Bu senaryolar arasındaki farklar ihtiyatla yorumlanmalıdır.",
      rule: "en az bir senaryonun güvenilirlik seviyesi düşük",
    });
  }
  return out;
}

/** Human-readable list of parameter differences between two scenarios. */
export function parameterChanges(a: Scenario, b: Scenario): string[] {
  const out: string[] = [];
  const ka = a.conditions;
  const kb = b.conditions;
  if (ka.objective !== kb.objective) return out;
  const ta = thresholdOf(ka);
  const tb = thresholdOf(kb);
  if (ta.label === tb.label && ta.value !== tb.value) {
    const fmt = (v: number) => (ta.unit === "TL" ? formatCurrency(v) : ta.unit === "%" ? `%${v}` : `${v}`);
    out.push(`${ta.label} ${fmt(ta.value)} → ${fmt(tb.value)}`);
  }
  const ra = describeReward(ka.reward);
  const rb = describeReward(kb.reward);
  if (ra !== rb) out.push(`Ödül ${ra} → ${rb}`);
  if (ka.durationDays !== kb.durationDays) out.push(`Süre ${ka.durationDays} → ${kb.durationDays} gün`);
  if (ka.budget !== kb.budget) out.push(`Bütçe ${formatCurrency(ka.budget, { compact: true })} → ${formatCurrency(kb.budget, { compact: true })}`);
  if (JSON.stringify(a.audience) !== JSON.stringify(b.audience)) out.push("Hedef kitle farklı");
  return out;
}

export function comparisonMetricsFor(scenarios: Scenario[]): KpiDefinition[] {
  if (!scenarios.length) return [];
  const objectives = new Set(scenarios.map((s) => s.objective));
  if (objectives.size === 1) return getObjective(scenarios[0].objective).comparisonMetrics;
  return getObjective("spending_growth").comparisonMetrics.filter((m) =>
    ["qualifiedCustomers", "qualificationRate", "observedSpending", "incrementalSpending", "totalCost", "budgetUtilization"].includes(m.key),
  );
}

/** Index of the "best" value per metric (direction-aware), for highlighting only. */
export function bestIndex(values: number[], lowerIsBetter?: boolean): number {
  let best = -1;
  values.forEach((v, i) => {
    if (!Number.isFinite(v) || v === 0) return;
    if (best === -1 || (lowerIsBetter ? v < values[best] : v > values[best])) best = i;
  });
  return best;
}
